// Generated by scripts/stitch-to-react.mjs from Stitch screen "Dev in_ 전체 질문 목록 (5번)" (10601936399347cda1caffc777e72f92).
// #23: 메인 화면. 질문 목록을 GET /api/questions에 연결하고 정렬 탭·페이지 번호를 붙였다.
import { useEffect, useState, type ReactNode } from "react";
import { Link, useSearchParams } from "react-router-dom";
import { getErrorMessage } from "../api/client";
import { getQuestions, type Page, type QuestionListItem, type QuestionSort } from "../api/question";
import Footer from "../components/Footer";
import Header from "../components/Header";
import "./Questions.css";

// Page-local styles from the Stitch <head>; mounted only while this page is shown.
const css =
  '/* Base canvas styling with cream background and subtle dot pattern */\n    body {\n      background-color: #FFFDF5;\n      background-image: radial-gradient(#d1cfc7 1px, transparent 1px);\n      background-size: 20px 20px;\n      color: #111111;\n      font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;\n    }\n\n    /* Standard Neo-brutalism borders and shadows */\n    .neo-border {\n      border: 2.5px solid #111111;\n    }\n    \n    .neo-border-b {\n      border-bottom: 2.5px solid #111111;\n    }\n\n    .neo-shadow {\n      box-shadow: 3px 3px 0px #111111;\n    }\n\n    .neo-shadow-sm {\n      box-shadow: 2px 2px 0px #111111;\n    }\n\n    .neo-shadow-active:active {\n      transform: translate(2px, 2px);\n      box-shadow: 0px 0px 0px #111111;\n    }';

const PAGE_SIZE = 10;
// 페이지 번호는 한 번에 이만큼만 보여준다 (‹ 1 2 3 4 5 ›).
const PAGE_WINDOW = 5;

const SORT_TABS: { value: QuestionSort; label: string }[] = [
  { value: "latest", label: "최신순" },
  { value: "views", label: "조회수순" },
  { value: "answers", label: "답변순" },
  { value: "likes", label: "좋아요순" },
];
const SORT_VALUES = SORT_TABS.map((tab) => tab.value);

// 상세 화면(#26)의 경로가 정해지면 여기만 바꾼다.
const detailPath = (questionId: number) => `/question-detail?questionId=${questionId}`;

// URL의 ?sort=&page=를 읽는다. 화면의 page는 1부터, API의 page는 0부터 시작한다.
function readListQuery(searchParams: URLSearchParams) {
  const sortParam = searchParams.get("sort") as QuestionSort | null;
  const sort = sortParam && SORT_VALUES.includes(sortParam) ? sortParam : "latest";
  const pageParam = Number(searchParams.get("page"));
  const page = Number.isInteger(pageParam) && pageParam >= 1 ? pageParam : 1;
  return { sort, page };
}

// "2026-11-08T10:00:00" → "2026.11.08"
function formatDate(createdAt: string) {
  return createdAt.slice(0, 10).replaceAll("-", ".");
}

// 1234 → "1.2k"
function formatCount(count: number) {
  return count >= 1000 ? `${(count / 1000).toFixed(1).replace(/\.0$/, "")}k` : String(count);
}

function pageNumbers(current: number, totalPages: number) {
  const start = Math.max(1, Math.min(current - Math.floor(PAGE_WINDOW / 2), totalPages - PAGE_WINDOW + 1));
  const end = Math.min(totalPages, start + PAGE_WINDOW - 1);
  return Array.from({ length: end - start + 1 }, (_, i) => start + i);
}

function QuestionItem({ question }: { question: QuestionListItem }) {
  return (
    <article className="p-4 sm:p-5 flex flex-col md:flex-row md:items-center justify-between gap-4 hover:bg-amber-50/40 transition-colors">
      <div className="flex items-start gap-4 min-w-0">
        <div className="w-16 flex-shrink-0 text-center text-xs leading-snug pt-0.5 font-medium text-gray-600">
          <div>
            {"좋아요 "}
            <span className="font-bold text-gray-900">{question.likeCount}</span>
          </div>
          <div>
            {"답변 "}
            <span className="font-bold text-gray-900">{question.answerCount}</span>
          </div>
          <div className="text-[11px] text-gray-400">조회 {formatCount(question.viewCount)}</div>
        </div>

        <div className="flex-1 min-w-0 space-y-1.5">
          <div className="flex items-center gap-2 flex-wrap">
            {question.accepted ? (
              <span className="px-1.5 py-0.5 bg-[#C7F9CC] text-[#0B5D1E] border border-[#111111] text-xs font-bold">
                해결됨
              </span>
            ) : (
              <span className="px-1.5 py-0.5 bg-gray-200 border border-gray-800 text-gray-800 text-xs font-bold">
                미해결
              </span>
            )}
            <Link
              className="font-bold text-base hover:underline text-gray-900 leading-tight break-all"
              to={detailPath(question.questionId)}
            >
              {question.title}
            </Link>
          </div>

          <div className="flex items-center gap-1.5 pt-1 flex-wrap">
            <span className="px-2 py-0.5 border border-[#111111] text-[#111111] text-[11px] font-bold bg-[#FFD43B]">
              {question.category.name}
            </span>
            {question.tags.map((tag) => (
              <span
                key={tag}
                className="px-2 py-0.5 border border-gray-400 text-gray-700 text-[11px] font-semibold bg-gray-50"
              >
                {tag}
              </span>
            ))}
          </div>
        </div>
      </div>

      <div className="text-xs text-gray-500 whitespace-nowrap self-end md:self-center font-medium">
        <span className="text-gray-900 font-semibold">{question.writer.nickname}</span>
        {` · ${formatDate(question.createdAt)}`}
      </div>
    </article>
  );
}

function StatusBox({ children }: { children: ReactNode }) {
  return <div className="p-10 text-center text-sm font-semibold text-gray-600">{children}</div>;
}

type LoadState =
  { status: "loading" } | { status: "error"; message: string } | { status: "done"; data: Page<QuestionListItem> };

export default function Questions() {
  const [searchParams, setSearchParams] = useSearchParams();
  const { sort, page } = readListQuery(searchParams);
  const [state, setState] = useState<LoadState>({ status: "loading" });
  const [retryKey, setRetryKey] = useState(0);

  useEffect(() => {
    let cancelled = false;
    setState({ status: "loading" });
    getQuestions({ sort, page: page - 1, size: PAGE_SIZE })
      .then((data) => {
        if (!cancelled) setState({ status: "done", data });
      })
      .catch((error: unknown) => {
        if (!cancelled) setState({ status: "error", message: getErrorMessage(error) });
      });
    return () => {
      cancelled = true;
    };
  }, [sort, page, retryKey]);

  function moveTo(next: { sort?: QuestionSort; page?: number }) {
    const params = new URLSearchParams();
    const nextSort = next.sort ?? sort;
    const nextPage = next.page ?? 1;
    if (nextSort !== "latest") params.set("sort", nextSort);
    if (nextPage > 1) params.set("page", String(nextPage));
    setSearchParams(params);
    window.scrollTo({ top: 0 });
  }

  const data = state.status === "done" ? state.data : null;
  const totalPages = data?.totalPages ?? 0;

  return (
    <div id="page-questions">
      <style>{css}</style>
      <div
        className="min-h-screen flex flex-col justify-between antialiased"
        style={{
          backgroundColor: "rgb(255, 253, 245)",
          backgroundImage: "radial-gradient(rgb(217, 212, 195) 1.2px, transparent 1.2px)",
          backgroundSize: "18px 18px",
        }}
      >
        <Header />

        <main className="flex-1 max-w-6xl w-full mx-auto px-4 sm:px-6 py-8">
          <div
            className="flex flex-col sm:flex-row items-start sm:items-end justify-between pb-3.5 gap-4"
            data-purpose="question-list-header"
          >
            <div className="flex items-baseline gap-2">
              <h1 className="text-2xl font-black tracking-tight text-gray-950">전체 질문</h1>
              {data && (
                <span className="text-sm font-semibold text-gray-500">{data.totalElements.toLocaleString()}개</span>
              )}
            </div>

            <div className="flex items-center neo-border bg-white p-0.5 neo-shadow-sm" role="tablist">
              {SORT_TABS.map((tab) => (
                <button
                  key={tab.value}
                  className={`px-3.5 py-1.5 text-xs font-bold transition-colors ${
                    tab.value === sort ? "bg-[#111111] text-white" : "text-gray-700 hover:bg-gray-100"
                  }`}
                  type="button"
                  role="tab"
                  aria-selected={tab.value === sort}
                  onClick={() => moveTo({ sort: tab.value })}
                >
                  {tab.label}
                </button>
              ))}
            </div>
          </div>

          <div
            className="neo-border bg-white neo-shadow divide-y-2 divide-neutral-900"
            data-purpose="question-items-container"
            aria-busy={state.status === "loading"}
          >
            {state.status === "loading" && <StatusBox>질문을 불러오는 중입니다...</StatusBox>}
            {state.status === "error" && (
              <StatusBox>
                <p className="text-[#E11D48]">{state.message}</p>
                <button
                  className="mt-4 h-9 px-4 bg-white border-2 border-[#111111] text-sm font-bold neo-shadow-sm neo-shadow-active"
                  type="button"
                  onClick={() => setRetryKey((key) => key + 1)}
                >
                  다시 시도
                </button>
              </StatusBox>
            )}
            {data && data.content.length === 0 && (
              <StatusBox>{page > 1 ? "이 페이지에는 질문이 없습니다." : "아직 등록된 질문이 없습니다."}</StatusBox>
            )}
            {data?.content.map((question) => (
              <QuestionItem key={question.questionId} question={question} />
            ))}
          </div>

          {totalPages > 1 && (
            <nav className="flex items-center justify-center gap-1.5 mt-8" aria-label="페이지 이동">
              <button
                className="w-9 h-9 bg-white border-2 border-[#111111] text-sm font-bold neo-shadow-sm neo-shadow-active disabled:opacity-40 disabled:shadow-none"
                type="button"
                aria-label="이전 페이지"
                disabled={page <= 1}
                onClick={() => moveTo({ page: page - 1 })}
              >
                ‹
              </button>
              {pageNumbers(page, totalPages).map((number) => (
                <button
                  key={number}
                  className={`w-9 h-9 border-2 border-[#111111] text-sm font-bold neo-shadow-sm neo-shadow-active ${
                    number === page ? "bg-[#FFD43B]" : "bg-white hover:bg-gray-100"
                  }`}
                  type="button"
                  aria-current={number === page ? "page" : undefined}
                  onClick={() => moveTo({ page: number })}
                >
                  {number}
                </button>
              ))}
              <button
                className="w-9 h-9 bg-white border-2 border-[#111111] text-sm font-bold neo-shadow-sm neo-shadow-active disabled:opacity-40 disabled:shadow-none"
                type="button"
                aria-label="다음 페이지"
                disabled={page >= totalPages}
                onClick={() => moveTo({ page: page + 1 })}
              >
                ›
              </button>
            </nav>
          )}
        </main>

        <Footer />
      </div>
    </div>
  );
}
